        private string HtmlEncodeText(string strText)
        {
            if (strText == null || strText.Length == 0)
                return "&nbsp;";
            return strText.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
        }

