        private string FormatDateHtml(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value)
                return "&nbsp;";
            try
            {
                DateTime dtm = Convert.ToDateTime(objValue);
                return dtm.ToString("dd/MM/yyyy");
            }
            catch
            {
                string str = Convert.ToString(objValue);
                if (str == null || str.Length < 1)
                    return "&nbsp;";
                return HtmlEncodeText(str);
            }
        }

        private string GetCellText(DataRow drw, string strField)
        {
            if (drw == null || !drw.Table.Columns.Contains(strField))
                return "&nbsp;";
            if (drw[strField] == DBNull.Value)
                return "&nbsp;";
            string str = Convert.ToString(drw[strField]);
            if (str == null || str.Length < 1)
                return "&nbsp;";
            return HtmlEncodeText(str);
        }

