        private void ExportSoGocTotNghiep_HTML()
        {
            DataTable dtbExport = GetExportDataTable();
            if (dtbExport == null || dtbExport.Rows.Count < 1)
            {
                ErrorManager.Error("Không có dữ liệu để xuất!");
                return;
            }

            string strCourseName = uScienceCourseTypeLevel.CourseName;
            if (strCourseName == null || strCourseName.Length < 1)
                strCourseName = Convert.ToString(dtbExport.Rows[0]["CourseName"]);

            string strTrainingType = uScienceCourseTypeLevel.TrainingTypeEditValue;
            if (strTrainingType == null || strTrainingType.Length < 1)
                strTrainingType = Convert.ToString(dtbExport.Rows[0]["TrainingType"]);

            string strDecisionNo = "";
            string strSigningDate = "";
            if (dtbExport.Rows[0]["DecisionNo"] != DBNull.Value)
                strDecisionNo = Convert.ToString(dtbExport.Rows[0]["DecisionNo"]);
            if (dtbExport.Rows[0]["Signingdate"] != DBNull.Value)
            {
                try
                {
                    DateTime dtmSign = Convert.ToDateTime(dtbExport.Rows[0]["Signingdate"]);
                    strSigningDate = dtmSign.ToString("dd/MM/yyyy");
                }
                catch
                {
                    strSigningDate = Convert.ToString(dtbExport.Rows[0]["Signingdate"]);
                }
            }

            string strCerNoFrom = "";
            string strCerNoTo = "";
            if (dtbExport.Rows[0]["CerNo"] != DBNull.Value)
                strCerNoFrom = Convert.ToString(dtbExport.Rows[0]["CerNo"]);
            if (dtbExport.Rows[dtbExport.Rows.Count - 1]["CerNo"] != DBNull.Value)
                strCerNoTo = Convert.ToString(dtbExport.Rows[dtbExport.Rows.Count - 1]["CerNo"]);

            DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
            string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
            if (strPlace == null || strPlace.Length < 1)
                strPlace = strReport_Place;
            string strPrintDate = (strPlace == null ? "" : strPlace)
                + ", ngày " + dtmNow.Day.ToString()
                + " tháng " + dtmNow.Month.ToString()
                + " năm " + dtmNow.Year.ToString();

            int intRowsPerPage = 18;
            int intTotal = dtbExport.Rows.Count;
            int intPageCount = (intTotal + intRowsPerPage - 1) / intRowsPerPage;
            string strTableHeader = BuildDataTableHeaderHtml();

            StringBuilder sb = new StringBuilder();
            sb.Append(BuildCoverPageHtml());

            for (int intPage = 0; intPage < intPageCount; intPage++)
            {
                bool bolLastPage = (intPage == intPageCount - 1);
                bool bolFirstPage = (intPage == 0);
                sb.Append("<div class='print-page").Append(bolLastPage ? " last-page" : "").Append("'>");

                if (bolFirstPage)
                {
                    sb.Append(BuildHtmlHeaderBlock());
                    sb.Append(BuildInfoBlockHtml(strCourseName, strTrainingType, strDecisionNo, strSigningDate));
                }

                sb.Append("<table class='data-table'>");
                sb.Append(strTableHeader);
                sb.Append("<tbody>");

                int intStart = intPage * intRowsPerPage;
                int intEnd = intStart + intRowsPerPage;
                if (intEnd > intTotal)
                    intEnd = intTotal;

                for (int i = intStart; i < intEnd; i++)
                    sb.Append(BuildDataTableRowHtml(dtbExport.Rows[i], i + 1));

                sb.Append("</tbody></table>");

                if (bolLastPage)
                    sb.Append(BuildFooterBlockHtml(intTotal, strCerNoFrom, strCerNoTo, strPrintDate));

                sb.Append("</div>");
            }

            string strTemplate = LoadHtmlTemplate("MauHtml\\Graduation\\ThongKeTotNghiep_SoGoc.htm", "Sổ gốc cấp phát bằng trung cấp");
            string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());
            SaveAndOpenHtml("ThongKeTotNghiep_SoGoc.htm", strFileContent);
        }

